use crate::{Result,sha256,workspace::{Grant,open_at},file_dispatch::list};
use serde::Serialize;use std::{collections::BTreeMap,os::unix::fs::MetadataExt};
#[derive(Clone,PartialEq)]struct Snapshot{device:u64,inode:u64,size:u64,hash:String}
#[derive(Serialize)]pub struct WatchEvent{pub sequence:u64,pub kind:String,pub relative_path:String,pub previous_path:Option<String>,pub sha256:Option<String>,pub size:Option<u64>,pub observed_at:f64}
#[derive(Default)]pub struct Watcher{snapshot:Option<BTreeMap<String,Snapshot>>,sequence:u64}
impl Watcher{
 fn event(&mut self,kind:&str,path:&str,previous:Option<String>,current:Option<&Snapshot>)->WatchEvent{self.sequence+=1;WatchEvent{sequence:self.sequence,kind:kind.into(),relative_path:path.into(),previous_path:previous,sha256:current.map(|s|s.hash.clone()),size:current.map(|s|s.size),observed_at:crate::now()}}
 pub fn scan(&mut self,g:&Grant,tenant:&str,user:&str)->Result<Vec<WatchEvent>>{g.authorize("watch",tenant,user)?;g.authorize("list",tenant,user)?;let mut current=BTreeMap::new();for entry in list(g,".",true)?{if entry.kind!="file"{continue}let capture=(||{let(parent,name)=g.parent(&entry.relative_path)?;let file=open_at(&parent,name.to_str().map_err(|_|crate::Error::Protocol)?,libc::O_RDONLY|libc::O_NONBLOCK,0)?;let m=file.metadata()?;let bytes=g.read(&entry.relative_path,8*1024*1024)?;Ok::<_,crate::Error>(Snapshot{device:m.dev(),inode:m.ino(),size:bytes.len() as u64,hash:sha256(&bytes)})})();if let Ok(snapshot)=capture{current.insert(entry.relative_path,snapshot);}}
 let Some(previous)=self.snapshot.take()else{self.snapshot=Some(current);return Ok(Vec::new())};let mut deleted:BTreeMap<_,_>=previous.iter().filter(|(p,_)|!current.contains_key(*p)).map(|(p,s)|(p.clone(),s.clone())).collect();let mut events=Vec::new();for(path,entry)in &current{if !previous.contains_key(path){let renamed=deleted.iter().find(|(_,old)|old.device==entry.device&&old.inode==entry.inode).map(|(p,_)|p.clone());if let Some(old)=renamed{deleted.remove(&old);events.push(self.event("rename",path,Some(old),Some(entry)));}else{events.push(self.event("create",path,None,Some(entry)));}}}for path in deleted.keys(){events.push(self.event("delete",path,None,None));}for(path,entry)in &current{if previous.get(path).is_some_and(|old|old!=entry){events.push(self.event("modify",path,None,Some(entry)));}}self.snapshot=Some(current);Ok(events)
 }
}
